catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
  if (isLoading || newValue == '') {
    return;
  }

  var ga = new GlideAjax('ScheduleUtils');
  ga.addParam('sysparm_name', 'getScheduleDate');
  ga.addParam('sysparm_schedule_id', newValue);
  ga.getXMLAnswer(function(response) {
    console.log("Data retornada:", response);


    var parts = response.split(/[- :]/);
    var scheduleDate = new Date(parts[0], parts[1] - 1, parts[2], parts[3], parts[4], parts[5]);

    var today = new Date();
    today.setHours(0, 0, 0, 0);
    scheduleDate.setHours(0, 0, 0, 0);

    var diffMs = scheduleDate.getTime() - today.getTime();
    var diffDays = diffMs / (1000 * 60 * 60 * 24);

    console.log("Diferença em dias:", diffDays);

    if (diffDays < 1) {
      g_form.showFieldMsg('schedule', "You can only apply for trainings that aren't within 1 day of being administered", 'error');
      g_form.setValue('schedule', '');
    }
  });
}
